import{_ as d,o,c as r,ac as e}from"./chunks/framework.Bzw8ikz_.js";const c=JSON.parse('{"title":"微前端","description":"","frontmatter":{},"headers":[],"relativePath":"front/micro/index.md","filePath":"front/micro/index.md","lastUpdated":1776041122000}'),i={name:"front/micro/index.md"};function n(a,t,l,p,s,h){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="微前端" tabindex="-1">微前端 <a class="header-anchor" href="#微前端" aria-label="Permalink to &quot;微前端&quot;">​</a></h1><p>微前端是一种多个团队通过独立发布功能的方式来共同构建现代化 web 应用的技术手段及方法策略。</p><p>微前端架构旨在解决单体应用在一个相对长的时间跨度下，由于参与的人员、团队的增多、变迁，从一个普通应用演变成一个<strong>巨石应用</strong>( Frontend Monolith)后，随之而来的应用不可维护的问题。</p><p><strong>微前端架构的核心价值：</strong></p><ol><li><p>技术栈无关</p><p>主框架不限制接入应用的技术栈，微应用具备完全自主权</p></li><li><p>独立开发、独立部署</p><p>微应用仓库独立，前后端可独立开发，部署完成后主框架自动完成同步更新</p></li><li><p>增量升级</p><p>在面对各种复杂场景时，我们通常很难对一个已经存在的系统做全量的技术栈升级或重构，而微前端是一种非常好的实施渐进式重构的手段和策略</p></li><li><p>独立运行时</p><p>每个微应用之间状态隔离，运行时状态不共享</p></li></ol><h1 id="微前端-micro-frontend-和-monorepo" tabindex="-1">微前端（Micro Frontend） 和 Monorepo <a class="header-anchor" href="#微前端-micro-frontend-和-monorepo" aria-label="Permalink to &quot;微前端（Micro Frontend） 和 Monorepo&quot;">​</a></h1><ol><li><p>Monorepo：代码组织方式</p><p>把多个项目 / 包放在同一个 Git 仓库里管理，解决<strong>代码复用、版本统一、构建效率</strong>问题。</p></li><li><p>微前端：运行时架构</p><p>多个独立应用在浏览器运行时组合成一个系统，解决<strong>独立部署、技术栈无关、团队自治问题</strong>。</p></li></ol><p><strong>区别：</strong></p><ul><li>Monorepo 是工程化方案，解决代码复用与版本一致性问题。</li><li>微前端是运行时架构，解决应用解耦与独立部署问题。</li><li>两者不冲突，大型项目通常一起用。 <ul><li>Monorepo 管理：公共组件、工具、类型、工具链</li><li>微前端管理：业务微应用（独立部署）</li></ul></li></ul><h1 id="常用微前端框架" tabindex="-1">常用微前端框架 <a class="header-anchor" href="#常用微前端框架" aria-label="Permalink to &quot;常用微前端框架&quot;">​</a></h1><table tabindex="0"><thead><tr><th>对比维度</th><th>qiankun（阿里）</th><th>wujie（无界）</th><th>MicroApp（京东）</th></tr></thead><tbody><tr><td>最核心原理</td><td>single-spa + Proxy 沙箱 + 样式隔离</td><td>同域 iframe + WebComponent</td><td>Proxy 沙箱 + CustomElement</td></tr><tr><td>沙箱方案</td><td>Proxy 沙箱 + 快照</td><td>同域 iframe 原生沙箱</td><td>Proxy 沙箱</td></tr><tr><td>样式隔离</td><td>ShadowDOM / 样式前缀</td><td>原生 WebComponent</td><td>模拟样式隔离</td></tr><tr><td>路由模式</td><td>路由劫持、单实例</td><td>原生 history 共享、多实例</td><td>虚拟路由、多实例</td></tr><tr><td>隔离强度</td><td>中（存在逃逸可能）</td><td>最高（浏览器级）</td><td>中（存在逃逸可能）</td></tr><tr><td>保活能力</td><td>不支持原生保活</td><td>真保活（iframe 实例保留）</td><td>模拟保活</td></tr><tr><td>接入成本</td><td>较高（需改造子应用）</td><td>极低（零改造）</td><td>低（低改造）</td></tr><tr><td>核心优势</td><td>生态成熟、兼容性广</td><td>隔离最强、最稳、零改造</td><td>最轻量、性能最好</td></tr></tbody></table><ul><li>qiankun：基于 single-spa 做路由调度，自己实现沙箱 / 样式 / 加载，是二次封装增强版</li><li>wujie：基于同域 iframe 实现原生 JS 沙箱，搭配 WebComponent 做样式隔离，零改造、真保活。</li><li>MicroApp：自研 Proxy 沙箱 + CustomElement 组件化渲染，轻量高性能、低侵入、多实例并行。</li></ul>',12)])])}const u=d(i,[["render",n]]);export{c as __pageData,u as default};
